def odd_square_sum(n):
    return sum(map(lambda x: x * x,
                   filter(lambda x: x % 2 == 1, range(1, n + 1))))

# odd_square_sum(10) = 1^2+3^2+5^2+7^2+9^2 = 165
# odd_square_sum(1) = 1

def accumulate(op, z, seq):
    if seq == []:
        return z
    return op(seq[0], accumulate(op, z, seq[1:]))


def my_map(f, seq):
    return accumulate(lambda x, xs: [f(x)] + xs, [], list(seq))


def my_filter(pred, seq):
    return accumulate(lambda x, xs: ([x] + xs) if pred(x) else xs, [], list(seq))


def sum_cubes_div_by_3(n):
    cubes = my_map(lambda k: k * k * k,
                   my_filter(lambda k: k % 3 == 0, range(1, n + 1)))
    return accumulate(lambda x, y: x + y, 0, cubes)

def naturals():
    n = 1
    while True:
        yield n
        n += 1


def map_lazy(f, iterable):
    for x in iterable:
        yield f(x)


def filter_lazy(pred, iterable):
    for x in iterable:
        if pred(x):
            yield x


def take(n, iterable):
    # Stop as soon as the n-th item arrives: asking for one more would pull
    # from the source again, and from naturals() that never has to end.
    out = []
    if n <= 0:
        return out
    for x in iterable:
        out.append(x)
        if len(out) == n:
            break
    return out


def first_odd_squares(k):
    return take(k, map_lazy(lambda x: x * x,
                            filter_lazy(lambda x: x % 2 == 1, naturals())))


# first_odd_squares(2) pulls 1 (kept), 2 (dropped), 3 (kept), then stops:
# three items from an infinite source.
print(first_odd_squares(5))  # [1, 9, 25, 49, 81]
